'use strict';

// MODULES //

var hasProp = require( '@stdlib/assert/has-property' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isObject = require( '@stdlib/assert/is-object' );
var objectAssign = require( '@stdlib/object/assign' );
var QuantitativeScale = require( '@stdlib/plot/vega/quantitative-scale' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns a function for creating a named quantitative scale.
*
* @param {string} name - default scale name
* @throws {TypeError} must provide a string
* @returns {Function} function for creating a named quantitative scale
*
* @example
* var xScale = factory( 'xScale' );
*
* var scale = xScale();
* // returns <QuantitativeScale>
*/
function factory( name ) {
	var defaults;
	if ( !isString( name ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a string. Value: `%s`.', name ) );
	}
	defaults = {
		'name': name
	};
	return createScale;

	/**
	* Returns a named quantitative scale.
	*
	* @private
	* @param {Options} [options] - function options
	* @throws {TypeError} options argument must be an object
	* @throws {Error} must provide valid options
	* @returns {QuantitativeScale} scale instance
	*/
	function createScale( options ) {
		var opts;
		if ( arguments.length ) {
			if ( !isObject( options ) ) {
				throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
			}
			if ( hasProp( options, 'name' ) ) {
				opts = options;
			} else {
				opts = objectAssign( {}, options );
				opts.name = defaults.name;
			}
			return new QuantitativeScale( opts );
		}
		return new QuantitativeScale( defaults );
	}
}


// EXPORTS //

module.exports = factory;
